ALTER TABLE public.cases     ADD COLUMN IF NOT EXISTS deleted_at TIMESTAMPTZ;
ALTER TABLE public.tasks     ADD COLUMN IF NOT EXISTS deleted_at TIMESTAMPTZ;
ALTER TABLE public.documents ADD COLUMN IF NOT EXISTS deleted_at TIMESTAMPTZ;

CREATE INDEX IF NOT EXISTS idx_cases_deleted_at     ON public.cases(deleted_at);
CREATE INDEX IF NOT EXISTS idx_tasks_deleted_at     ON public.tasks(deleted_at);
CREATE INDEX IF NOT EXISTS idx_documents_deleted_at ON public.documents(deleted_at);

DROP POLICY IF EXISTS "lawyers_or_team_select_cases" ON public.cases;
CREATE POLICY "lawyers_or_team_select_cases" ON public.cases
  FOR SELECT TO authenticated
  USING (
    lawyer_id = auth.uid()
    OR client_id = auth.uid()
    OR EXISTS (
      SELECT 1 FROM public.team_members tm
      WHERE tm.office_lawyer_id = public.cases.lawyer_id
        AND tm.member_profile_id = auth.uid()
        AND tm.is_active = true
        AND tm.can_view_all_cases = true
    )
  );

ON CONFLICT DO NOTHING;