INSERT INTO public.legal_statutes (law_name, law_number, law_year, article_number, article_text, topic_tags) VALUES
  ('قانون المرافعات', '13/1968', 1968, '228', 'ميعاد الاستئناف في القضايا الإدارية ستون يوماً من تاريخ إعلان الحكم أو الإجراء الإداري المطعون فيه.', ARRAY['استئناف','إدارية','مواعيد']),
  ('قانون المرافعات', '13/1968', 1968, '415', 'يبدأ التنفيذ الجبري بناءً على سند تنفيذي تثبت به حقوق محققة الوجود ومعينة المقدار وحالة الأداء، ويسبقه إعلان السند وتكليف بالوفاء.', ARRAY['تنفيذ جبري','سند تنفيذي']),
  ('قانون المرافعات', '13/1968', 1968, '332', 'لكل ذي شأن أن يرفع إشكالاً وقتياً في التنفيذ بطلب وقفه أو الاستمرار فيه، ويُرفع الإشكال أمام قاضي التنفيذ بإجراءات الدعوى المستعجلة.', ARRAY['إشكالات تنفيذ','وقف تنفيذ']),
  ('قانون المرافعات', '13/1968', 1968, '280', 'إذا كان حق الدائن ثابتاً بالكتابة وحال الأداء وكان كل ما يطالب به ديناً من النقود معين المقدار، فله أن يستصدر أمراً بالأداء.', ARRAY['أمر أداء','دين']),
  ('قانون المرافعات', '13/1968', 1968, '281', 'للمدين أن يتظلم من أمر الأداء خلال عشرة أيام من تاريخ إعلانه به، ويعد التظلم بمثابة استئناف.', ARRAY['تظلم','أمر أداء','مواعيد']),
  ('قانون المرافعات', '13/1968', 1968, '52', 'تنعقد الخصومة بتقديم صحيفة الدعوى إلى قلم كتاب المحكمة وقيدها في يومها.', ARRAY['دعوى','صحيفة']),
  ('قانون المرافعات', '13/1968', 1968, '63', 'يجب أن يتضمن إعلان صحيفة الدعوى البيانات الجوهرية وإلا كانت الصحيفة باطلة.', ARRAY['بطلان','إعلان']),
  ('القانون المدني', '131/1948', 1948, '147', 'إذا طرأت بعد إبرام العقد وقبل تمام تنفيذه حوادث استثنائية عامة لم يكن في الوسع توقعها، وترتب على حدوثها أن تنفيذ الالتزام التعاقدي وإن لم يصبح مستحيلاً صار مرهقاً للمدين بحيث يهدده بخسارة فادحة، جاز للقاضي تبعاً للظروف ردّ الالتزام المرهق إلى الحد المعقول.', ARRAY['ظروف طارئة','إرهاق','عقود']),
  ('القانون المدني', '131/1948', 1948, '148', 'يجب تنفيذ العقد طبقاً لما اشتمل عليه وبطريقة تتفق مع ما يوجبه حسن النية.', ARRAY['حسن نية','تنفيذ عقد']),
  ('القانون المدني', '131/1948', 1948, '157', 'في العقود الملزمة للجانبين إذا لم يوف أحد المتعاقدين بالتزامه جاز للمتعاقد الآخر بعد إعذاره المدين أن يطالب بتنفيذ العقد أو فسخه مع التعويض إن كان له مقتضى.', ARRAY['فسخ','إخلال','تعويض']),
  ('القانون المدني', '131/1948', 1948, '163', 'كل خطأ سبب ضرراً للغير يلزم من ارتكبه بالتعويض.', ARRAY['مسؤولية','تعويض','خطأ']),
  ('القانون المدني', '131/1948', 1948, '170', 'يقدر القاضي مدى التعويض عن الضرر الذي لحق المضرور طبقاً لأحكام المادتين 221 و222 مراعياً في ذلك الظروف الملابسة.', ARRAY['تعويض','ضرر']),
  ('القانون المدني', '131/1948', 1948, '232', 'لا يجوز للدائن أن يطالب بتعويض عن الضرر إلا إذا أعذر المدين، ما لم ينص القانون أو الاتفاق على غير ذلك.', ARRAY['إعذار','تعويض']),
  ('القانون المدني', '131/1948', 1948, '374', 'يتقادم الالتزام بانقضاء خمس عشرة سنة فيما عدا الحالات التي ورد عنها نص خاص في القانون.', ARRAY['تقادم','15 سنة']),
  ('القانون المدني', '131/1948', 1948, '378', 'يتقادم بثلاث سنوات: حقوق الأطباء والصيادلة والمحامين والمهندسين والخبراء، وذلك فيما أدوه من عمل وما تكبدوه من مصروفات.', ARRAY['تقادم','مهنيون','3 سنوات']),
  ('القانون المدني', '131/1948', 1948, '394', 'تنقضي بمضي ثلاث سنوات دعوى المسؤولية الناشئة عن العمل غير المشروع من يوم علم المضرور بحدوث الضرر وبالشخص المسؤول عنه.', ARRAY['تقادم','مسؤولية تقصيرية']),
  ('قانون الشركات', '159/1981', 1981, '40', 'يكون رأس مال الشركة المساهمة مقسماً إلى أسهم متساوية القيمة قابلة للتداول، ولا يقل رأس المال المصدر عن ربع رأس المال المرخص به.', ARRAY['شركة مساهمة','رأس مال']),
  ('قانون الشركات', '159/1981', 1981, '53', 'تخضع الشركة المساهمة لرقابة مراقب حسابات يعينه الجمعية العامة العادية لمدة سنة قابلة للتجديد.', ARRAY['مراقب حسابات']),
  ('قانون الشركات', '159/1981', 1981, '76', 'تدار الشركة المساهمة بمجلس إدارة لا يقل عدد أعضائه عن ثلاثة، ويعينون لمدة لا تجاوز ثلاث سنوات قابلة للتجديد.', ARRAY['مجلس إدارة']),
  ('قانون الشركات', '159/1981', 1981, '128', 'تنحل الشركة في الأحوال الآتية: انتهاء مدتها، تحقق الغرض من تأسيسها، هلاك جميع مالها، اندماجها، صدور قرار قضائي بحلها.', ARRAY['انحلال','شركة']),
  ('قانون الشركات', '159/1981', 1981, '165', 'يجوز للشركاء في شركة الأشخاص الانسحاب منها بإرادتهم المنفردة بشرط الإخطار قبل نهاية السنة المالية بثلاثة أشهر على الأقل.', ARRAY['انسحاب','شركاء']),
  ('قانون التوقيع الإلكتروني', '15/2004', 2004, '14', 'للتوقيع الإلكتروني في نطاق المعاملات المدنية والتجارية والإدارية ذات الحجية المقررة للتوقيعات في أحكام قانون الإثبات في المواد المدنية والتجارية متى استوفى الشروط المنصوص عليها في هذا القانون.', ARRAY['توقيع إلكتروني','حجية']),
  ('قانون التوقيع الإلكتروني', '15/2004', 2004, '15', 'للكتابة الإلكترونية وللمحررات الإلكترونية في نطاق المعاملات المدنية والتجارية والإدارية ذات الحجية المقررة في أحكام قانون الإثبات.', ARRAY['كتابة إلكترونية','إثبات']),
  ('قانون التوقيع الإلكتروني', '15/2004', 2004, '18', 'يُعدّ التوقيع الإلكتروني مرتبطاً بصاحبه دون غيره متى ارتبط بالموقع وحده، وكان كافياً لتحديد شخصه، وللموقع وحده السيطرة عليه عند استخدامه.', ARRAY['توقيع','تحقق']),
  ('قانون حماية المستهلك', '181/2018', 2018, '4', 'يحظر على المورد أن يقدم بيانات أو معلومات أو إعلانات كاذبة أو مضللة عن السلعة أو الخدمة محل التعامل.', ARRAY['إعلان مضلل','حماية مستهلك']),
  ('قانون حماية المستهلك', '181/2018', 2018, '8', 'للمستهلك الحق في استبدال السلعة أو إعادتها مع رد قيمتها خلال أربعة عشر يوماً من تسلمها إذا اكتشف بها عيباً أو لم تكن مطابقة للمواصفات المعلنة.', ARRAY['استبدال','رد','14 يوم']),
  ('قانون حماية المستهلك', '181/2018', 2018, '9', 'يجب على المورد أن يضمن المنتج لفترة معقولة، وأن يقدم خدمة ما بعد البيع وقطع الغيار اللازمة لمدة لا تقل عن المدة المحددة في اللائحة التنفيذية.', ARRAY['ضمان','خدمة ما بعد البيع']),
  ('قانون حماية المستهلك', '181/2018', 2018, '17', 'لا يجوز للمورد تضمين عقود الإذعان شروطاً تعفيه من المسؤولية أو تضع على المستهلك التزامات تعسفية.', ARRAY['عقد إذعان','شروط تعسفية']),
  ('قانون حماية المستهلك', '181/2018', 2018, '60', 'يعاقب بغرامة لا تقل عن عشرة آلاف جنيه ولا تجاوز مليون جنيه كل من خالف أحكام المواد 4 و8 و9 من هذا القانون.', ARRAY['عقوبة','غرامة']),
  ('قانون العمل', '12/2003', 2003, '69', 'لا يجوز لصاحب العمل إنهاء عقد العمل غير محدد المدة بإرادته المنفردة إلا لسبب مشروع كافٍ، وبعد إخطار العامل كتابة قبل الإنهاء بمدة شهرين إن كانت مدة الخدمة لا تجاوز عشر سنوات.', ARRAY['إنهاء','إخطار','عمل']),
  ('قانون العمل', '12/2003', 2003, '110', 'لكل عامل أمضى سنة كاملة في الخدمة الحق في إجازة سنوية مدتها 21 يوماً، تزاد إلى 30 يوماً متى أمضى في الخدمة عشر سنوات أو بلغ الخمسين من عمره.', ARRAY['إجازة سنوية']),
  ('قانون العمل', '12/2003', 2003, '122', 'للعامل المؤمن عليه الحق في إجازة مرضية بأجر كامل لا تجاوز 75% من المرتب الأساسي خلال التسعين يوماً الأولى من المرض.', ARRAY['إجازة مرضية']),
  ('قانون العمل', '12/2003', 2003, '125', 'إذا أنهى صاحب العمل العقد دون مبرر مشروع، التزم بأن يؤدي للعامل تعويضاً لا يقل عن أجر شهرين عن كل سنة من سنوات الخدمة.', ARRAY['فصل تعسفي','تعويض']),
  ('قانون الأحوال الشخصية', '25/1929', 1929, '17', 'لا تسمع دعوى الزوجية أو الإقرار بها بعد وفاة أحد الزوجين إلا إذا كانت ثابتة بأوراق خالية من شبهة التزوير.', ARRAY['زوجية','إثبات']),
  ('قانون الأحوال الشخصية', '25/1929', 1929, '20', 'للزوجة التي عقد عليها صحيحاً أن تطلب من القاضي التطليق منه إذا أبى الزوج طلاقها للضرر الذي لا يستطاع معه دوام العشرة.', ARRAY['تطليق','ضرر']),
  ('قانون الأحوال الشخصية', '1/2000', 2000, '20', 'للزوجين أن يتراضيا بينهما على الخلع، فإن لم يتراضيا عليه وأقامت الزوجة دعواها به وافتدت نفسها بالتنازل عن جميع حقوقها المالية وردت إليه الصداق، حكم بتطليقها عليه.', ARRAY['خلع']),
  ('قانون العقوبات', '58/1937', 1937, '76', 'كل من ارتكب جريمة سرقة بطريق الإكراه أو التهديد به يعاقب بالأشغال الشاقة المؤقتة.', ARRAY['سرقة','إكراه']),
  ('قانون العقوبات', '58/1937', 1937, '236', 'من أحدث عمداً بغيره إصابة أو ضرباً أفضى إلى الموت ولم يقصد منها قتلاً يعاقب بالأشغال الشاقة من ثلاث سنين إلى سبع.', ARRAY['ضرب أفضى للموت']),
  ('قانون العقوبات', '58/1937', 1937, '241', 'من أحدث بغيره جرحاً أو ضرباً بطلت منفعة عضو من أعضائه يعاقب بالحبس مدة لا تقل عن سنتين.', ARRAY['ضرب','عاهة'])
